def transform(grid):
    h = len(grid)
    out = [[0] * 7 for _ in range(h)]

    marker_col = next(
        c for row in grid for c, value in enumerate(row) if value == 5
    )
    x = marker_col - 8
    y = 1
    out[0][x] = 5

    # Tile patterns encode a stroke: direction and length.
    strokes = {
        ((1, 1, 0), (1, 0, 1), (0, 1, 0)): ("right", 3),
        ((1, 0, 1), (1, 0, 1), (1, 1, 1)): ("left", 2),
        ((1, 0, 1), (0, 1, 0), (0, 1, 0)): ("down", 2),
        ((1, 1, 1), (0, 1, 0), (1, 0, 1)): ("left", 4),
    }

    # Follow the tiles down the left column, then down the right column.
    for base_col in (0, 4):
        for top in range(0, h - 2, 4):
            tile = [
                grid[top + dr][base_col:base_col + 3]
                for dr in range(3)
            ]
            mask = tuple(tuple(int(v != 0) for v in row) for row in tile)
            if mask not in strokes:
                continue

            color = next(v for row in tile for v in row if v != 0)
            direction, length = strokes[mask]

            if direction == "down":
                for dy in range(length):
                    if 0 <= y + dy < h and 0 <= x < 7:
                        out[y + dy][x] = color
                y += length
            else:
                step = 1 if direction == "right" else -1
                for dx in range(length):
                    col = x + step * dx
                    if 0 <= y < h and 0 <= col < 7:
                        out[y][col] = color
                x += step * (length - 1)
                y += 1

    return out
